data.content:
MSTest doesn't have `Assert.IsGreaterThan` or `Assert.IsInRange` — those don't exist. Here's what to use instead:

**Comparison options in MSTest:**

| Need | Use |
|------|-----|
| Value in range | `Assert.IsTrue(value >= min && value <= max)` |
| Greater than | `Assert.IsTrue(value > expected)` |
| Equality with tolerance | `Assert.AreEqual(expected, actual, delta)` |
| Exception thrown | `Assert.ThrowsException<T>(action)` |

The `Assert.AreEqual(double, double, double)` overload is your best tool for floating-point results — the third parameter is the allowed tolerance (delta).

Here's a test class for your `ScoreCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Contoso.Scoring;

namespace Contoso.Scoring.Tests;

[TestClass]
public class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    [TestMethod]
    public void CalculatePercentage_PerfectScore_Returns100()
    {
        Assert.AreEqual(100.0, _calculator.CalculatePercentage(10, 10), 0.001);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroCorrect_Returns0()
    {
        Assert.AreEqual(0.0, _calculator.CalculatePercentage(0, 10), 0.001);
    }

    [TestMethod]
    public void CalculatePercentage_ResultAlwaysBetween0And100()
    {
        double result = _calculator.CalculatePercentage(7, 10);
        Assert.IsTrue(result >= 0.0 && result <= 100.0,
            $"Expected [0, 100] but got {result}");
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(5, 0));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }

    [TestMethod]
    [DataRow(90.0, "A")]
    [DataRow(89.9, "B")]
    [DataRow(80.0, "B")]
    [DataRow(79.9, "C")]
    [DataRow(70.0, "C")]
    [DataRow(69.9, "D")]
    [DataRow(60.0, "D")]
    [DataRow(59.9, "F")]
    public void GetGrade_BoundaryValues_ReturnsExpectedGrade(double percentage, string expected)
    {
        Assert.AreEqual(expected, _calculator.GetGrade(percentage));
    }

    [TestMethod]
    public void NormalizeScore_ResultNeverExceeds100()
    {
        double result = _calculator.NormalizeScore(150.0, 100.0);
        Assert.IsTrue(result <= 100.0, $"Expected <= 100 but got {result}");
    }

    [TestMethod]
    public void NormalizeScore_HalfOfMax_Returns50()
    {
        Assert.AreEqual(50.0, _calculator.NormalizeScore(25.0, 50.0), 0.001);
    }

    [TestMethod]
    public void NormalizeScore_NegativeRawScore_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(-1.0, 100.0));
    }
}
```

**Key patterns:**
- **`Assert.AreEqual(expected, actual, 0.001)`** — floating-point equality with delta tolerance
- **`Assert.IsTrue(condition, message)`** — range/comparison checks (include a message for debuggability)
- **`Assert.ThrowsException<T>`** — boundary violation exceptions
- **`[DataRow]`** — great for testing grade boundaries systematically
